38	    /**
39	     * Colonna riempita dal trait con l'ultimo utente che ha salvato.
40	     */
41	    protected static ?string $updatedByColumn = 'updated_by';
42	
43	    protected $guarded = [];
44	
45	    /**
46	     * Colonne reali su cui il driver "database" di Scout costruisce le
47	     * LIKE (roadmap #23): le chiavi devono corrispondere a colonne della
48	     * tabella, non a valori arbitrari. `name_search` è una colonna generata
49	     * STORED (cast a testo di `name`, JSON translatable): MySQL confronta il
50	     * JSON grezzo con LIKE usando collation binaria (case-sensitive) a
51	     * prescindere dalla collation di connessione, il cast la aggira. Match
52	     * grezzo su tutte le lingue incluso.
53	     *
54	     * @return array<string, mixed>
55	     */
56	    public function toSearchableArray(): array
57	    {
58	        return [
59	            'name_search' => $this->getAttribute('name_search'),
60	            'slug' => $this->slug,
61	        ];
62	    }
