64	    protected static function booted(): void
65	    {
66	        // strategia orfani (opzione C, design §3.6): al salvataggio rimuove dal JSON
67	        // degli attributi le chiavi non più previste dallo schema corrente (risolto
68	        // dalla tipologia già assegnata sul record). L'utente è avvisato a monte
69	        // dall'alert inline nel ProductForm; qui avviene lo strip effettivo.
70	        static::saving(function (self $product): void {
71	            // se la tipologia è cambiata, la relazione productType potrebbe essere
72	            // ancora quella vecchia in cache: la scarico così lo schema viene
73	            // risolto dalla tipologia appena assegnata.
74	            if ($product->isDirty('product_type_id')) {
75	                $product->unsetRelation('productType');
76	            }
77	
78	            $product->setAttribute(
79	                $product->attributesColumn(),
80	                $product->stripOrphanAttributes($product->attributeSchema()),
81	            );
82	        });
83	    }
84	
85	    /**
86	     * Lo schema attributi del Product è determinato dalla ProductType associata.
87	     * Se la ProductType non ha uno schema configurato, il prodotto non ha attributi tipizzati.
88	     */
89	    public function resolveAttributeSchemaClass(): ?string
90	    {
91	        $class = $this->productType?->attribute_schema_class;
92	
93	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
94	    }
