147	     *
148	     * @return BelongsToMany<Material, $this>
149	     */
150	    public function materials(): BelongsToMany
151	    {
152	        return $this->belongsToMany(Material::class, 'material_product', 'product_id', 'material_id');
153	    }
154	
155	    /**
156	     * Materiali assegnati al prodotto che, tra i loro tag, ne hanno uno con il
157	     * dato valore sull'asse "finalità" (es. struttura, piano_tavolo, ...).
158	     *
159	     * @return BelongsToMany<Material, $this>
160	     */
161	    public function materialsForFinalita(string $value): BelongsToMany
162	    {
163	        $tags = Tag::query()->withMeta('info_prodotto:finalita', $value)->get();
164	
165	        if ($tags->isEmpty()) {
166	            throw new InvalidArgumentException("Nessun tag trovato per info_prodotto:finalita = \"{$value}\"");
167	        }
168	
169	        return $this->materials()->withAnyTags($tags);
170	    }
