5	namespace App\Http\Resources\Api;
6	
7	use App\Models\Product;
8	use AtrioTeam\DigitalHub\Pim\Enum\Type;
9	use Illuminate\Http\Request;
10	use Illuminate\Http\Resources\Json\JsonResource;
11	
12	/**
13	 * Payload di un Product per l'API esterna (roadmap #24).
14	 *
15	 * `name` è translatable: esce come mappa `locale => valore` con **tutte** le
16	 * lingue configurate (`config('digital-hub.locales')`), non risolto in una
17	 * sola — il CMS deve poter fare il mirror completo in un giro di sync solo.
18	 *
19	 * Prima entità esposta con attributi PIM popolati (`ProductAttributes`, via
20	 * `HasTechnicalAttributes`): il CMS non conosce lo schema, quindi qui gli
21	 * attributi escono **già risolti**, per tutte le lingue configurate:
22	 * - `label`: mappa locale => label tradotta dell'attributo;
23	 * - `value`: mappa locale => valore, se l'attributo è `translatable()` o
24	 *   `Enum` (il valore mostrato è la label dell'opzione, non la chiave
25	 *   canonica); altrimenti un valore singolo (numeri e date non dipendono
26	 *   dalla lingua);
27	 * - `unit`: singola, non dipende dalla lingua.
28	 * Le chiavi senza valore non compaiono (coerenti con lo strip degli orfani
29	 * lato scrittura).
30	 *
31	 * `deleted_at` non nullo segnala un record soft-deleted (`ApiResourceController`
32	 * lo include nel payload, non lo filtra): è così che il CMS/client vede una
33	 * cancellazione nello stesso sync incrementale su `updated_since`, invece di
34	 * vedere il record sparire senza spiegazione.
35	 *
36	 * @mixin Product
37	 */
38	class ProductResource extends JsonResource
39	{
40	    /**
41	     * @return array<string, mixed>
42	     */
43	    public function toArray(Request $request): array
44	    {
45	        return [
46	            // Chiave di join cross-sistema, non l'id: l'id locale dell'hub non
47	            // è un'identità stabile per il consumatore.
48	            'global_id' => $this->global_id,
49	            'name' => $this->getTranslations('name'),
50	            'slug' => $this->slug,
51	            'category_global_id' => $this->category2?->global_id,
52	            'product_type_global_id' => $this->productType?->global_id,
53	            'attributes' => $this->resolveAttributes(),
54	            'updated_at' => $this->updated_at?->toIso8601String(),
55	            'deleted_at' => $this->deleted_at?->toIso8601String(),
56	        ];
57	    }
58	
59	    /**
60	     * @return array<string, array{label: array<string, string>, value: mixed, unit: ?string}>
61	     */
62	    private function resolveAttributes(): array
63	    {
64	        $schema = $this->attributeSchema();
65	        if ($schema === null) {
66	            return [];
67	        }
68	
69	        $locales = array_keys((array) config('digital-hub.locales', []));
70	        /** @var array<string, mixed> $rawValues */
71	        $rawValues = (array) $this->getAttribute($this->attributesColumn());
72	
73	        $resolved = [];
74	
75	        foreach ($schema->attributes() as $key => $type) {
76	            $raw = $rawValues[$key] ?? null;
77	            if ($this->isBlank($raw)) {
78	                continue;
79	            }
80	
81	            $value = $type->isTranslatable()
82	                ? $this->mapLocales($locales, fn (string $locale): mixed => $this->attr($key, $locale))
83	                : $this->attr($key);
84	
85	            if ($type->kind() === Type::Enum && is_string($value)) {
86	                $value = $this->mapLocales($locales, fn (string $locale): string => $this->attrOption($key, $value, $locale));
87	            }
88	
89	            $resolved[$key] = [
90	                'label' => $this->mapLocales($locales, fn (string $locale): string => $this->attrLabel($key, $locale)),
91	                'value' => $value,
92	                'unit' => $type->getUnit(),
93	            ];
94	        }
95	
96	        return $resolved;
97	    }
98	
99	    /**
100	     * @template T
101	     * @param list<string> $locales
102	     * @param callable(string): T $resolve
103	     * @return array<string, T>
104	     */
105	    private function mapLocales(array $locales, callable $resolve): array
106	    {
107	        $map = [];
108	        foreach ($locales as $locale) {
109	            $map[$locale] = $resolve($locale);
110	        }
111	
112	        return $map;
113	    }
114	
115	    private function isBlank(mixed $raw): bool
116	    {
117	        if (is_array($raw)) {
118	            return $raw === [] || collect($raw)->every(static fn (mixed $v): bool => $v === null || $v === '');
119	        }
120	
121	        return $raw === null || $raw === '';
122	    }
123	}
