53	
54	        $highlightedKey = request()->query('tableActionRecord');
55	
56	        if (! is_string($highlightedKey)) {
57	            return;
58	        }
59	
60	        $perPage = $this->getTableRecordsPerPage();
61	
62	        if (! is_numeric($perPage)) {
63	            // 'all' o non ancora risolto: nessuna paginazione da saltare.
